WITH CustomerSummary AS (SELECT customer_id, ROUND((100 * SUM(CASE WHEN plan = 'standard' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_standard, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(plan))) AS plan_values FROM subscriptions WHERE MONTH(end_date) IN (2, 5, 12) GROUP BY customer_id) SELECT c.email, c.is_active, C.pct_standard, C.plan_values FROM customers c INNER JOIN CustomerSummary C ON c.id = C.customer_id WHERE C.pct_standard >= 33 ORDER BY email DESC;
